#!/usr/bin/env bash
###
# install-rick-sanchez-sounds.sh
# Self-contained installer for Rick Sanchez (Rick and Morty) sound effects for Claude Code hooks.
# All 19 .mp3 files are embedded (base64) — no external downloads needed.
#
# Events:
#   SessionStart      → "Wubba lubba dub dub!" / "What's going on" / "Yo ding dong" / "There's a lot more where that came from"
#   UserPromptSubmit  → "Shut up and listen" / "Sure why not" / "Just a yes or no" / "Pass the butter" / "I need you to do me a favor"
#   Stop              → "Well that's retarded" / "How about that drink" / "Kind of makes you wonder" / "Thanks Mr Poopy Butthole" / "This isn't a musical number" / "Screw this"
#   Notification      → "I can't abide bureaucracy" / "Poor use of my time" / "What do you think I can just do it all by myself" / "Whatever you want to do" (permission prompts only)
#
# Prerequisites:
#   - macOS (uses afplay)
#   - jq
#
# Usage: bash install-rick-sanchez-sounds.sh
###
set -euo pipefail

HOOKS_DIR="$HOME/.claude/hooks"
SOUNDS_DIR="$HOOKS_DIR/sounds/rick_sanchez"
SETTINGS="$HOME/.claude/settings.json"
HOOK_SCRIPT="$HOOKS_DIR/rick-sanchez-sound.sh"

# -- Preflight checks --
if ! command -v jq &>/dev/null; then
  echo "Error: jq is required. Install with: brew install jq" >&2
  exit 1
fi

if [[ "$(uname)" != "Darwin" ]]; then
  echo "Warning: This hook uses macOS 'afplay'. You may need to swap the player command on Linux." >&2
fi

# -- Create directories --
mkdir -p "$SOUNDS_DIR"
mkdir -p "$(dirname "$SETTINGS")"

echo "Extracting 19 Rick Sanchez sound files..."

base64 -D << 'B64EOF' > "$SOUNDS_DIR/how-about-that-drink.mp3"
