B64EOF

echo "Extracted all sound files to $SOUNDS_DIR"

# -- Write the hook script --
cat > "$HOOK_SCRIPT" << 'HOOKEOF'
#!/usr/bin/env bash
# rick-sanchez-sound: play Rick Sanchez sounds on Claude Code hook events
set -euo pipefail

SOUNDS_DIR="$HOME/.claude/hooks/sounds/rick_sanchez"

# Read hook JSON from stdin
INPUT=$(cat)

EVENT=$(echo "$INPUT" | jq -r '.hook_event_name // ""' 2>/dev/null)

# Map events to sound categories
case "$EVENT" in
  SessionStart)
    SOUNDS=(well-beloved-dub-dub.mp3 what-s-going-on.mp3 yo-ding-dong.mp3 there-s-a-lot-more-where-that-came-from-too.mp3)
    ;;
  UserPromptSubmit)
    SOUNDS=(shut-up-and-listen-to-me.mp3 sure-why-not-i-don-t-i-don-t-know.mp3 just-a-yes-or-no.mp3 pass-the-butter.mp3 i-need-you-to-do-me-a-favor.mp3)
    ;;
  Stop)
    SOUNDS=(well-that-s-retarded.mp3 how-about-that-drink.mp3 kind-of-makes-you-wonder-huh.mp3 thanks-mr-poopy-butt-hole-i-always-could-count-on-you.mp3 this-isn-t-a-musical-number-this-is-a-fucking-operation-we-gotta-be-cool-and-fucking-lay-low.mp3 screw-this.mp3)
    ;;
  Notification)
    # Check if it's a permission prompt
    IS_PERMISSION=$(echo "$INPUT" | jq -r '.notification_type // ""' 2>/dev/null)
    if [ "$IS_PERMISSION" = "permission_prompt" ] || echo "$INPUT" | jq -e 'tostring | test("permission"; "i")' >/dev/null 2>&1; then
      SOUNDS=(i-can-t-abide-bureaucracy-i-don-t-like-being-told-where-to-go-and-what-to-do-i-consider-it-a-violation.mp3 poor-use-of-my-time-it-s-beneath-me.mp3 what-do-you-think-i-can-just-do-it-all-by-myself.mp3 whatever-you-want-to-do-you-little-punk-ass-little-bitch.mp3)
    else
      exit 0
    fi
    ;;
  *)
    exit 0
    ;;
esac

# Pick a random sound
COUNT=${#SOUNDS[@]}
INDEX=$((RANDOM % COUNT))
SOUND_FILE="$SOUNDS_DIR/${SOUNDS[$INDEX]}"

# Play it (macOS)
if [ -f "$SOUND_FILE" ]; then
  afplay "$SOUND_FILE" &
fi
HOOKEOF

chmod +x "$HOOK_SCRIPT"
echo "Wrote hook script: $HOOK_SCRIPT"

# -- Merge hook entries into settings.json --
if [ ! -f "$SETTINGS" ]; then
  echo '{}' > "$SETTINGS"
fi

HOOK_CMD="\$HOME/.claude/hooks/rick-sanchez-sound.sh"
HOOK_ENTRY='{"type":"command","command":"'"$HOOK_CMD"'","timeout":5,"async":true}'

EVENTS=("SessionStart" "UserPromptSubmit" "Stop" "Notification")

for event in "${EVENTS[@]}"; do
  ALREADY=$(jq --arg evt "$event" --arg cmd "$HOOK_CMD" '
    (.hooks[$evt] // [])
    | map(.hooks // [])
    | flatten
    | any(.command == $cmd)
  ' "$SETTINGS")

  if [ "$ALREADY" = "true" ]; then
    echo "Hook already registered for $event — skipping"
    continue
  fi

  jq --arg evt "$event" --argjson entry "$HOOK_ENTRY" '
    .hooks //= {} |
    if (.hooks[$evt] | length) > 0 then
      .hooks[$evt][0].hooks += [$entry]
    else
      .hooks[$evt] = [{"matcher":"","hooks":[$entry]}]
    end
  ' "$SETTINGS" > "${SETTINGS}.tmp" && mv "${SETTINGS}.tmp" "$SETTINGS"

  echo "Registered hook for $event"
done

echo ""
echo "Done! Rick Sanchez sounds are now hooked into Claude Code."
echo "  Session start  → \"Wubba lubba dub dub!\" / \"What\'s going on\" / \"Yo ding dong\""
echo "  Prompt submit  → \"Shut up and listen\" / \"Sure why not\" / \"Just a yes or no\" / \"Pass the butter\""
echo "  Task complete  → \"Well that\'s retarded\" / \"How about that drink\" / \"Thanks Mr Poopy Butthole\""
echo "  Permission ask → \"I can\'t abide bureaucracy\" / \"Poor use of my time\" / \"Whatever you want to do\""
